package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/**
 * A grade of a person, in force from its from-date (or from the beginning of time when it has none) until the
 * person's next later-dated grade.
 */
@Entity
@Table(name = "person_grade")
public class PersonGrade {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** The date the grade applies from; null for the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    protected PersonGrade() {
    }

    PersonGrade(String grade, LocalDate fromDate) {
        this.grade = grade;
        this.fromDate = fromDate;
    }

    public String getGrade() {
        return grade;
    }

    void setGrade(String grade) {
        this.grade = grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }
}
-- A person's grade is dated: each grade applies from its from-date on, until the person's next
-- later-dated grade takes over. The first grade a person was given has no from-date and applies
-- from the beginning of time. A person has at most one grade per from-date (and at most one with
-- none); from_key stands in for the missing from-date so the unique index covers that one too.
CREATE TABLE person_grade (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL,
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_person_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
-- Each sheet keeps its own "today": every date-dependent decision and default date uses it, never
-- the real clock. A sheet starts with the real date of the day it was created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
