/**
 * Whether the claim counts in the live totals: an OPEN, PENDING or SETTLED one, but an OPEN or PENDING one not while
 * its person is held.
 */
function live(claim: Claim, held: boolean): boolean {
  return counts(claim) && !(held && isOpen(claim));
}

